import { test, expect } from '@playwright/test';

test.describe('Profile Picture Upload and Preview', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should successfully upload a profile picture and display preview', async ({ page }) => {
    // Locate and click the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload profile picture/i });
    await uploadButton.click();

    // Locate and select a file using getByLabel
    const fileInput = page.getByLabel(/profile picture/i);
    await fileInput.setInputFiles('fixtures/profile.jpg');

    // Locate and verify the preview image using getByRole
    const previewImage = page.getByRole('img', { name: /profile picture preview/i });
    await expect(previewImage).toBeVisible();

    // Verify the preview image has loaded
    const previewImageSrc = await previewImage.evaluate((el) => el.src);
    expect(previewImageSrc).toContain('profile.jpg');

    // Verify the preview image has correct dimensions
    const previewWidth = await previewImage.evaluate((el) => el.clientWidth);
    const previewHeight = await previewImage.evaluate((el) => el.clientHeight);
    expect(previewWidth).toBeGreaterThan(100);
    expect(previewHeight).toBeGreaterThan(100);

    // Verify the preview image is visible
    await expect(previewImage).toBeVisible();

    // Verify the preview image has correct aspect ratio
    const previewAspectRatio = previewWidth / previewHeight;
    expect(previewAspectRatio).toBeCloseTo(1);

    // Verify the preview image has correct file size
    const previewFileSize = await previewImage.evaluate((el) => el.files[0].size);
    expect(previewFileSize).toBeLessThan(1000000);

    // Verify the preview image has correct file type
    const previewFileType = await previewImage.evaluate((el) => el.files[0].type);
    expect(previewFileType).toBe('image/jpeg');

    // Verify the preview image has correct alt text
    const previewAltText = await previewImage.evaluate((el) => el.getAttribute('alt'));
    expect(previewAltText).toBe('Profile Picture');

    // Verify the preview image has correct title
    const previewTitle = await previewImage.evaluate((el) => el.getAttribute('title'));
    expect(previewTitle).toBe('Profile Picture Preview');

    // Verify the preview image has correct border
    const previewBorder = await previewImage.evaluate((el) => el.getAttribute('style').includes('border'));
    expect(previewBorder).toBeTruthy();

    // Verify the preview image has correct background color
    const previewBackgroundColor = await previewImage.evaluate((el) => window.getComputedStyle(el).getPropertyValue('background-color'));
    expect(previewBackgroundColor).toBe('rgb(255, 255, 255)');

    // Verify the preview image has correct opacity
    const previewOpacity = await previewImage.evaluate((el) => window.getComputedStyle(el).getPropertyValue('opacity'));
    expect(previewOpacity).toBe('1');

    // Verify the preview image has correct filter
    const previewFilter = await previewImage.evaluate((el) => window.getComputedStyle(el).getPropertyValue('filter'));
    expect(previewFilter).toBe('none');

    // Verify the preview image has correct transform
    const previewTransform = await previewImage.evaluate((el) => window.getComputedStyle(el).getPropertyValue('transform'));
